A **vector** is a pair of numbers (x, y). Games use it for a **position** (where), a **velocity** (how fast, and which way) and an **acceleration** (how the velocity changes). Every engine and maths library has one (`glm::vec2`, raylib's `Vector2`, Unreal's `FVector2D`); this course grows the `Vec2` from the C++ lesson into a small header, and the snippets from here on include it:

```cpp
// vec2.h
#pragma once
#include <cmath>
#include <ostream>

struct Vec2 {
    float x = 0, y = 0;

    Vec2& operator+=(Vec2 o) { x += o.x; y += o.y; return *this; }
    Vec2& operator-=(Vec2 o) { x -= o.x; y -= o.y; return *this; }

    float length() const { return std::sqrt(x * x + y * y); }
    Vec2 normalized() const {
        float len = length();
        return len > 0 ? Vec2{x / len, y / len} : *this;
    }
};

inline Vec2 operator+(Vec2 a, Vec2 b) { return {a.x + b.x, a.y + b.y}; }
inline Vec2 operator-(Vec2 a, Vec2 b) { return {a.x - b.x, a.y - b.y}; }
inline Vec2 operator*(Vec2 v, float k) { return {v.x * k, v.y * k}; }
inline Vec2 operator/(Vec2 v, float k) { return {v.x / k, v.y / k}; }
inline float dot(Vec2 a, Vec2 b) { return a.x * b.x + a.y * b.y; }

inline std::ostream& operator<<(std::ostream& os, Vec2 v) {
    return os << '(' << v.x << ", " << v.y << ')';
}
```

It is two floats, so it is passed **by value** everywhere, and `operator<<` prints it as `(x, y)`.

