The same steps in C++, on a 5×5 map where `#` is a wall:

```cpp
struct Tile { int r, c; };

int steps(const std::vector<std::string>& map) {
    int rows = static_cast<int>(map.size()), cols = static_cast<int>(map[0].size());
    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));   // -1: not visited
    std::queue<Tile> frontier;
    dist[0][0] = 0;                               // S is in the top-left corner
    frontier.push({0, 0});

    while (!frontier.empty()) {
        Tile t = frontier.front();                // oldest tile first
        frontier.pop();
        if (map[t.r][t.c] == 'G') return dist[t.r][t.c];
        Tile next[] = {{t.r - 1, t.c}, {t.r + 1, t.c}, {t.r, t.c - 1}, {t.r, t.c + 1}};
        for (Tile n : next) {
            bool open = n.r >= 0 && n.r < rows && n.c >= 0 && n.c < cols && map[n.r][n.c] != '#';
            if (open && dist[n.r][n.c] == -1) {   // not visited yet
                dist[n.r][n.c] = dist[t.r][t.c] + 1;
                frontier.push(n);
            }
        }
    }
    return -1;                                    // no path
}

int main() {
    std::vector<std::string> map{
        "S.#..",
        "..#..",
        "....G",
        ".###.",
        ".....",
    };
    std::printf("%d\n", steps(map));
}
```

It prints `6`. `dist` starts at −1 everywhere, so "visited" just means "has a distance". `std::queue` hands tiles back in the order they went in.

