#include <iostream>
#include <sstream>
#include <string>

struct SaveData { int version = 0, seed = 0, health = 0, maxHealth = 0; };

SaveData load(std::istream& in) {
    SaveData s;
    std::string key;
    while (in >> key) {
        if (key == "version") in >> s.version;
        else if (key == "seed") in >> s.seed;
        else if (key == "health") in >> s.health;
        else if (key == "maxHealth") in >> s.maxHealth;
    }
    if (s.version < 2) { s.version = 2; s.maxHealth = 5; }   // version 1 had no maxHealth
    return s;
}

int main() {
    std::istringstream oldSave("version 1\nseed 42\nhealth 3\n");
    std::istringstream newSave("version 2\nseed 42\nhealth 3\nmaxHealth 8\n");
    for (SaveData s : {load(oldSave), load(newSave)})
        std::cout << 'v' << s.version << ' ' << s.health << '/' << s.maxHealth << '\n';
}

#include <cmath>
#include <cstdio>
#include "vec2.h"

struct Cell { int x, y; };

Cell cellOf(Vec2 p, float size) {
    return {static_cast<int>(p.x / size), static_cast<int>(p.y / size)};
}

int main() {
    Vec2 points[] = {{9.5f, 2}, {-1, 2}, {1, 2}};
    for (Vec2 p : points) {
        Cell c = cellOf(p, 4);
        std::printf("(%d, %d)\n", c.x, c.y);
    }
}
